	osSyncPrintf("HEAD_GREY ismale: %d\n", g_HeadsAndBodies[HEAD_GREY].ismale);

	// Fallback to ismale check (works if compiled with AIO flag)
	if (HEAD_GREY >= 0 && HEAD_GREY < ARRAYCOUNT(g_HeadsAndBodies)) {
		g_AIOPresent = !g_HeadsAndBodies[HEAD_GREY].ismale;
	}

	osSyncPrintf("AIO detected: %d\n", g_AIOPresent);

	mpSetArenaMode(g_AIOPresent);
	g_Vars.aioffset += 2;
	return false;
}

