// Female-only head indices for Friends of Joanna carousel
// These map to mpheadnum values from Combat Simulator
#define FOJO_HEAD_JOANNA    MPHEAD_DARK_COMBAT  // 0x00 - Joanna Dark
#define FOJO_HEAD_VELVET    MPHEAD_VD           // 0x0b - Velvet Dark
#define FOJO_HEAD_MIKADO    0x4b                // Japanese Jo (from AIO detection)
#define FOJO_HEAD_POPLIN    MPHEAD_DARK_SNOW    // 0x03 - Poplin Dark (snow outfit)

// Array of female heads for the carousel (4 fixed + player's CS head)
u8 g_FojoHeadOptions[] = {
	FOJO_HEAD_JOANNA,
	FOJO_HEAD_VELVET,
	FOJO_HEAD_MIKADO,
	FOJO_HEAD_POPLIN,
	0 // 5th slot for player's CS head
};

// Get the appropriate female head for a player
// If player's CS head is male or Brett Jones, return a female alternative
s32 fojoGetPlayerHead(s32 playernum)
{
	s32 cshead = g_PlayerConfigsArray[playernum].base.mpheadnum;
	s32 headnum = mpGetHeadId(cshead);

	// Special case: Brett Jones always becomes Cassandra
	if (cshead == MPHEAD_JONES) {
		return MPHEAD_CASSANDRA;
	}

	// Check if the head is male in g_HeadsAndBodies
	if (headnum >= 0 && headnum < ARRAYCOUNT(g_HeadsAndBodies)) {
		if (g_HeadsAndBodies[headnum].ismale) {
			// Pick a random female head
			return g_MpFemaleHeads[rngRandom() % ARRAYCOUNT(g_MpFemaleHeads)];
		}
	}

	// Already female, return as-is
	return cshead;
}

MenuItemHandlerResult menuhandlerTeamOperativeHeadPlayer(s32 operation, struct menuitem *item, union handlerdata *data, s32 playernum)
{
	static struct modelpartvisibility visibility[] = {
		{ MODELPART_HEAD_SUNGLASSES, false },
		{ MODELPART_HEAD_EYESCLOSED, false },
		{ MODELPART_HEAD_HUDPIECE,   false },
		{ 255, false },
	};

	switch (operation) {
	case MENUOP_CHECKDISABLED:
		if (!g_Vars.playerroles[playernum]) {
			return true;
		}
		break;

	case MENUOP_GETOPTIONCOUNT:
		// 4 fixed options + 1 for player's CS profile head
		data->carousel.value = 5;
		break;

	case MENUOP_11:
		// Update the 5th slot with player's appropriate head
		g_FojoHeadOptions[4] = fojoGetPlayerHead(playernum);
		data->carousel.value = g_PlayerConfigsArray[playernum].teamagentindex;
		break;

	case MENUOP_SET:
		g_PlayerConfigsArray[playernum].teamagentindex = data->carousel.value;
		// Store the selected mpheadnum for later use
		break;

	case MENUOP_GETSELECTEDINDEX:
		data->carousel.value = g_PlayerConfigsArray[playernum].teamagentindex;
		if (data->carousel.value >= 5) {
			data->carousel.value = 0;
		}
		break;

	case MENUOP_17:
		// Render the head model
		g_FojoHeadOptions[4] = fojoGetPlayerHead(playernum);
		{
			s32 selectedindex = g_PlayerConfigsArray[playernum].teamagentindex;
			if (selectedindex >= 0 && selectedindex < 5) {
				s32 mpheadnum = g_FojoHeadOptions[selectedindex];
				s32 headnum = mpGetHeadId(mpheadnum);

				if (headnum >= 0) {
					g_Menus[g_MpPlayerNum].menumodel.newparams = MENUMODELPARAMS_SET_FILENUM(g_HeadsAndBodies[headnum].filenum);
					modelSetNodeVisibility(&g_Menus[g_MpPlayerNum].menumodel, visibility);
				}
			}
		}
		break;
	}

	return 0;
}

