edits.text:
// Get the appropriate female head for a player
// If player's CS head is male, return a female alternative
s32 fojoGetPlayerHead(s32 playernum)
{
	s32 cshead = g_PlayerConfigsArray[playernum].base.mpheadnum;
	s32 maxheads = mpGetNumHeads2();

	// Check if CS head is out of bounds for current mode (vanilla vs AIO)
	// Vanilla has 72 heads (0x00-0x48 including MOTO), AIO has 75+ (includes Mikado at 0x4b)
	// If AIO not present and head >= 0x49 (73), fall back to Joanna Dark
	if (!g_AIOPresent && cshead >= 73) {
		return 0; // Joanna Dark
	}

	// If head is completely out of bounds, fall back to Joanna
	if (cshead < 0 || cshead >= maxheads) {
		return 0;
	}

	s32 headnum = mpGetHeadId(cshead);

	// If CS head is female, return it as-is
	if (headnum >= 0 && headnum < ARRAYCOUNT(g_HeadsAndBodies)) {
		if (!g_HeadsAndBodies[headnum].ismale) {
			return cshead;
		}
	}

