+	// skip until }
+	int depth = 1;
+	while (p && token[0] && depth > 0) {
+		p = strParseToken(p, token, NULL);
+		if (!strcmp(token, "{")) depth++;
+		else if (!strcmp(token, "}")) depth--;
+	}
+	return p;
+}
